export function total(values) {
  if (values.length === 0) return 0;
  let sum = 0;
  for (const value of values) {
    if (typeof value !== 'number' || !isFinite(value)) {
      throw new Error('Non-numeric or non-finite value');
    }
    sum += value;
  }
  return sum;
}
